#!/bin/sh
# Prints the Homebrew formula of a release: formula.sh VERSION SUMS, where SUMS is the
# SHA256SUMS.txt of the release. The tap realfamousbae/homebrew-wolfpack keeps it in
# Formula/wolfpack.rb; the workflow `packages.yml` updates it when a release is published.
set -eu
version=$1
sums=$2
sum() {
    awk -v f="$1" '$2 == f || $2 == "*" f { print $1 }' "$sums"
}
base="https://github.com/realfamousbae/wolfpack/releases/download/v$version"
cat <<RUBY
# Generated by release/homebrew/formula.sh of the wolfpack repository for each release.
class Wolfpack < Formula
  desc "Statically typed language that compiles to readable TypeScript, Go and Rust"
  homepage "https://github.com/realfamousbae/wolfpack"
  license any_of: ["MIT", "Apache-2.0"]

  # The macOS archive is universal: the same file for both processors.
  on_macos do
    on_arm do
      url "$base/wolfpack-macos-universal.tar.gz"
      sha256 "$(sum wolfpack-macos-universal.tar.gz)"
    end
    on_intel do
      url "$base/wolfpack-macos-universal.tar.gz"
      sha256 "$(sum wolfpack-macos-universal.tar.gz)"
    end
  end

  on_linux do
    on_intel do
      url "$base/wolfpack-linux-x64.tar.gz"
      sha256 "$(sum wolfpack-linux-x64.tar.gz)"
    end
    on_arm do
      url "$base/wolfpack-linux-arm64.tar.gz"
      sha256 "$(sum wolfpack-linux-arm64.tar.gz)"
    end
  end

  def install
    bin.install "wolf"
  end

  def caveats
    <<~EOS
      wolf runs programs in its own VM without other tools (wolf run --vm).
      To build and run them as TypeScript, Go or Rust, install those tools with:
        wolf setup
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/wolf --version")
    system bin/"wolf", "new", "hello"
    assert_equal "Hello, wolfpack!\n", shell_output("cd hello && #{bin}/wolf run --vm")
  end
end
RUBY
